const ADMIN_PASSWORD='VisaLand2027!';
const defaultContent={heroEyebrow:'Авторские путешествия · Азия',heroTitle:'Путешествия, <span>которые <em>запоминаются</em></span>',heroCopy:'Япония, Корея и другие страны. Продуманные маршруты, небольшие группы и забота на каждом этапе.',introTitle:'Мы создаём истории,<br>которые хочется <em>пересказывать</em>',introCopy:'В каждом маршруте — знаменитые места и маленькие открытия, локальная кухня, живые города и время почувствовать страну без спешки.',manifestoTitle:'Не по шаблону.<br><em>По-настоящему.</em>',manifestoLead:'Путешествие должно оставлять место для жизни.',manifestoCopy:'Поэтому между главными точками маршрута мы сохраняем время для спонтанных прогулок, любимых кафе и разговоров, после которых группа становится командой.',aboutTitle:'Путешествия, которые я создаю <em>с любовью к деталям</em>',aboutCopy:'Меня зовут Гаухар. Я организую путешествия и лично сопровождаю часть групп. Для меня важно не просто показать известные места, а создать комфортный, живой и запоминающийся маршрут.'};
const contentLabels={heroEyebrow:'Надпись над главным заголовком',heroTitle:'Главный заголовок',heroCopy:'Описание первого экрана',introTitle:'Заголовок вступления',introCopy:'Текст вступления',manifestoTitle:'Заголовок «Наш подход»',manifestoLead:'Подзаголовок «Наш подход»',manifestoCopy:'Текст «Наш подход»',aboutTitle:'Заголовок «О проекте»',aboutCopy:'Основной текст «О проекте»'};
const defaultTours=[
 {id:'korea-japan',title:'Корея + Япония',route:'Сеул — Пусан — Осака — Киото — Нара — Токио',dates:'20–29 марта 2027',days:'10 дней',price:'от $2 850',places:'6 мест',status:'Открыт набор',image:'/assets/media/tour-korea-japan.jpg'},
 {id:'japan-korea',title:'Япония + Корея',route:'Токио — Киото — Осака — Нара — Пусан — Сеул',dates:'12–21 апреля 2027',days:'10 дней',price:'от $2 950',places:'3 места',status:'Осталось несколько мест',image:'/assets/media/tour-japan-korea.jpg'},
 {id:'other-japan',title:'Другая Япония',route:'Канадзава — Такаяма — Коясан — Наосима',dates:'8–20 мая 2027',days:'13 дней',price:'от $3 650',places:'Скоро',status:'Скоро анонс',image:'/assets/media/tour-other-japan.jpg'},
 {id:'private-asia',title:'Ваша Азия',route:'Маршрут создаём вместе',dates:'В удобные даты',days:'от 7 дней',price:'по запросу',places:'Индивидуально',status:'Принимаем заявки',image:'/assets/media/tour-private-asia.jpg'}
];
const sectionNames={hero:'Первый экран',intro:'Вступление',trips:'Форматы и туры',manifesto:'Наш подход',calendar:'Календарь',about:'О проекте',gallery:'Галерея',faq:'Вопросы и ответы',contact:'Форма заявки'};
const defaultOrder=Object.keys(sectionNames);let order=[];let uploadValues={};
function showDashboard(){document.querySelector('#login-panel').hidden=true;document.querySelector('#dashboard').hidden=false;renderEditor()}
if(sessionStorage.getItem('visaLandAdmin')==='true')showDashboard();
document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();const entered=document.querySelector('#password').value.trim().replace(/^`|`$/g,'');if(entered===ADMIN_PASSWORD){sessionStorage.setItem('visaLandAdmin','true');showDashboard()}else document.querySelector('#login-error').textContent='Неверный пароль'};
document.querySelector('#logout').onclick=()=>{sessionStorage.removeItem('visaLandAdmin');location.reload()};
document.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(el=>el.classList.remove('active'));btn.classList.add('active');document.querySelector(`[data-panel="${btn.dataset.tab}"]`).classList.add('active')});
function config(){return JSON.parse(localStorage.getItem('visaLandConfig')||'{}')}
function renderEditor(){const saved=config();const content={...defaultContent,...saved.content};document.querySelector('#content-fields').innerHTML=Object.entries(contentLabels).map(([key,label])=>`<label class="field ${key.endsWith('Copy')?'wide':''}"><span>${label}</span><textarea name="content.${key}" rows="${key.endsWith('Copy')?4:2}">${content[key]}</textarea></label>`).join('');const tours=defaultTours.map(t=>({...t,...(saved.tours||[]).find(x=>x.id===t.id)}));document.querySelector('#tour-fields').innerHTML=tours.map((t,i)=>`<article class="tour-editor" data-tour="${t.id}"><div class="tour-preview" style="background-image:url('${t.image}')"></div><div><h3>${t.title}</h3><div class="tour-inputs">${['title','route','dates','days','price','places','status','image'].map(key=>`<label class="field ${key==='route'||key==='image'?'wide':''}"><span>${({title:'Название',route:'Маршрут',dates:'Даты',days:'Длительность',price:'Цена',places:'Места',status:'Статус',image:'URL фотографии'})[key]}</span><input name="tour.${i}.${key}" value="${String(t[key]||'').replaceAll('"','&quot;')}"></label>`).join('')}<label class="field wide"><span>Загрузить фотографию</span><input class="upload" type="file" accept="image/jpeg,image/png,image/webp" data-upload="${t.id}"></label><input type="hidden" name="tour.${i}.id" value="${t.id}"></div></div></article>`).join('');document.querySelectorAll('[data-upload]').forEach(input=>input.onchange=()=>readImage(input));order=Array.isArray(saved.sectionOrder)?[...saved.sectionOrder]:[...defaultOrder];renderOrder()}
function readImage(input){const file=input.files[0];if(!file)return;if(file.size>1500000){alert('Файл слишком большой. Используйте изображение до 1,5 МБ.');input.value='';return}const reader=new FileReader();reader.onload=()=>{uploadValues[input.dataset.upload]=reader.result;input.closest('.tour-editor').querySelector('.tour-preview').style.backgroundImage=`url('${reader.result}')`};reader.readAsDataURL(file)}
function renderOrder(){document.querySelector('#section-order').innerHTML=order.map((key,i)=>`<li><span>${String(i+1).padStart(2,'0')} · ${sectionNames[key]}</span><div class="order-actions"><button type="button" data-move="up" data-key="${key}" aria-label="Выше"><span class="chevron up"></span></button><button type="button" data-move="down" data-key="${key}" aria-label="Ниже"><span class="chevron down"></span></button></div></li>`).join('');document.querySelectorAll('[data-move]').forEach(btn=>btn.onclick=()=>move(btn.dataset.key,btn.dataset.move))}
function move(key,direction){const i=order.indexOf(key),to=direction==='up'?i-1:i+1;if(to<0||to>=order.length)return;[order[i],order[to]]=[order[to],order[i]];renderOrder()}
document.querySelector('#editor-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),content={},tours=defaultTours.map((base,i)=>{const item={id:base.id};['title','route','dates','days','price','places','status','image'].forEach(key=>item[key]=fd.get(`tour.${i}.${key}`)||'');if(uploadValues[base.id])item.image=uploadValues[base.id];return item});Object.keys(defaultContent).forEach(key=>content[key]=fd.get(`content.${key}`)||'');localStorage.setItem('visaLandConfig',JSON.stringify({content,tours,sectionOrder:order}));const status=document.querySelector('#save-status');status.textContent='Сохранено. Обновите главную страницу.';setTimeout(()=>status.textContent='',4000)};
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset-site').onclick=()=>dialog.showModal();document.querySelector('#cancel-reset').onclick=()=>dialog.close();document.querySelector('#confirm-reset').onclick=()=>{localStorage.removeItem('visaLandConfig');uploadValues={};dialog.close();renderEditor();document.querySelector('#save-status').textContent='Исходная версия восстановлена.'};
